SELECT order_id, status, CASE WHEN amount >= 1700 THEN 'high' WHEN amount >= 390 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(amount) - MIN(amount) AS amount_range, COUNT(DISTINCT amount) AS unique_statuss FROM payments GROUP BY order_id, status, CASE WHEN amount >= 1700 THEN 'high' WHEN amount >= 390 THEN 'mid' ELSE 'low' END HAVING COUNT(DISTINCT amount) >= 1 ORDER BY unique_statuss DESC, order_id, status, amount_bucket LIMIT 10;
